contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _test(uint256 _val) internal {
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.SetMinSum(_val) {} catch { return; }
        assertTrue(c.MinSum() == _val);
    }

    function testFuzz_test(uint256 _val) public {
        _test(_val);
    }

    receive() external payable {}

    fallback() external {}
}
